import{_ as e,o as a,a as d,b as _}from"./app.BGziXukh.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"试验接口","link":"/api/SIMD-API/c_api/experimental/experimental"},{"text":"概述","link":"/api/SIMD-API/c_api/experimental/overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/experimental/overview.md","filePath":"api/SIMD-API/c_api/experimental/overview.md","outlineHeaders":[{"level":2,"title":"试验接口概述","slug":"试验接口概述","link":"#试验接口概述"},{"level":2,"title":"API列表","slug":"API列表","link":"#API列表"},{"level":3,"title":"试验接口","slug":"试验接口","link":"#试验接口"},{"level":3,"title":"相关类型","slug":"相关类型","link":"#相关类型"}],"lastUpdated":1794017913000}'),r={name:"api/SIMD-API/c_api/experimental/overview.md"};function i(l,t,c,p,o,s){return a(),d("div",null,[...t[0]||(t[0]=[_('<div><article class="markdown-body"><h1>概述</h1><h2 id="试验接口概述">试验接口概述<a class="header-anchor" href="#试验接口概述">​</a></h2><p>试验接口提供双返回值形式的寄存器计算、数据搬运及指令发射队列状态查询能力。使用时需定义<code>CANN_ASC_USE_EXPERIMENTAL</code>宏，并显式包含对应头文件；后续版本不保证兼容性。</p><h2 id="API列表">API列表<a class="header-anchor" href="#API列表">​</a></h2><h3 id="试验接口">试验接口<a class="header-anchor" href="#试验接口">​</a></h3><p><strong>表1</strong> 试验接口</p><table><thead><tr><th>接口名称</th><th>接口描述</th><th>最细粒度公共头文件</th></tr></thead><tbody><tr><td><a href="asc_get_pipe_idle_slot_count.html">asc_get_pipe_mte2_idle_slot_count、asc_get_pipe_mte3_idle_slot_count、asc_get_pipe_v_idle_slot_count、asc_get_pipe_m_idle_slot_count、asc_get_pipe_mte1_idle_slot_count、asc_get_pipe_fix_idle_slot_count</a></td><td>获取指定流水线对应发射队列当前的空闲槽位数量。</td><td><code>c_api/experimental/asc_get_pipe_idle_slot_count.h</code></td></tr><tr><td><a href="asc_add_carry.html">asc_add_carry</a></td><td>按掩码执行32位逐元素加法，同时返回加法结果和进位标志，支持带输入进位的运算。</td><td><code>c_api/experimental/reg_arith_exp.h</code></td></tr><tr><td><a href="asc_sub_carry.html">asc_sub_carry</a></td><td>按掩码执行32位逐元素减法，同时返回减法结果和进位标志；进位为1表示无借位，为0表示有借位。</td><td><code>c_api/experimental/reg_arith_exp.h</code></td></tr><tr><td><a href="asc_mull.html">asc_mull</a></td><td>按掩码将32位元素相乘，分别返回64位乘积的低32位和高32位。</td><td><code>c_api/experimental/reg_arith_exp.h</code></td></tr><tr><td><a href="asc_intlv.html">asc_intlv</a></td><td>对两个源矢量数据寄存器或掩码寄存器进行交织，返回两个寄存器结果。</td><td><code>c_api/experimental/reg_permute_sel_exp.h</code></td></tr><tr><td><a href="asc_deintlv.html">asc_deintlv</a></td><td>对两个源矢量数据寄存器或掩码寄存器进行解交织，返回两个寄存器结果。</td><td><code>c_api/experimental/reg_permute_sel_exp.h</code></td></tr><tr><td><a href="asc_loadalign_deintlv.html">asc_loadalign_deintlv</a></td><td>从UB的32字节对齐地址读取2×VL长度数据，分别返回偶数下标和奇数下标元素。</td><td><code>c_api/experimental/loadalign_exp.h</code></td></tr></tbody></table><h3 id="相关类型">相关类型<a class="header-anchor" href="#相关类型">​</a></h3><p><strong>表2</strong> 相关类型</p><table><thead><tr><th>名称</th><th>描述</th><th>最细粒度公共头文件</th></tr></thead><tbody><tr><td><a href="pair.html">双返回值结构体</a></td><td>通过<code>first</code>和<code>second</code>两个成员承载试验接口返回的两个寄存器结果。</td><td><code>c_api/experimental/pair.h</code></td></tr></tbody></table></article></div>',1)])])}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
